$ErrorActionPreference='Stop'
$root='D:/VScode/项目/提示词工具/.dsh-workspace/.verification/dsh-web-template-probe-20261102'
$profile=Join-Path $root 'profiles/forward-step-web-probe'
$log=Join-Path $root 'web-probe.stdout.log';$err=Join-Path $root 'web-probe.stderr.log';$cli='D:/deepseek/resources/runtime/cli/bin/dsh.cmd';$env:DSH_HOME=$root
$proc=Start-Process -FilePath 'pwsh.exe' -ArgumentList @('-NoProfile','-Command',"`$env:DSH_HOME='$root'; & '$cli' --profile forward-step-web-probe --no-open --host 127.0.0.1 --port 0") -RedirectStandardOutput $log -RedirectStandardError $err -WindowStyle Hidden -PassThru
try{$line=$null;for($i=0;$i -lt 30;$i++){Start-Sleep -Milliseconds 500;if(Test-Path $log){$line=Get-Content $log -Raw;if($line -match '(http://127\.0\.0\.1:\d+/\?token=[^\s]+)'){break}}};if($line -notmatch '(http://127\.0\.0\.1:\d+/\?token=[^\s]+)'){throw 'authenticated Web URL missing'};$uri=$Matches[1];$base=[Uri]$uri;$r=Invoke-WebRequest -Uri $uri -TimeoutSec 15 -SkipHttpErrorCheck;$html=if($r.Content -is [byte[]]){[Text.Encoding]::UTF8.GetString($r.Content)}else{[string]$r.Content};$rows=@();$patterns=@('(?s)<script[^>]*>(.*?)</script>','(?s)<script[^>]*id=.?__DSH_BOOT__.?[^>]*>(.*?)</script>','(?s)window\.__DSH_BOOT__\s*=\s*(\{.*?\})\s*;');foreach($pat in $patterns){foreach($m in [regex]::Matches($html,$pat)){$s=$m.Groups[1].Value;if($s.Contains('forward-step-dsh') -or $s.Contains('"profile"')){$rows+=@{pattern=$pat;length=$s.Length;forwardStepCount=([regex]::Matches($s,'forward-step-dsh')).Count;prefix=$s.Substring(0,[Math]::Min(80,$s.Length))}}}};$pluginRoutes=@([regex]::Matches($html,'plugins/[^"<> ]{0,250}forward-step-dsh[^"<> ]{0,250}')|%{$_.Value});[pscustomobject]@{httpStatus=$r.StatusCode;scriptNodes=([regex]::Matches($html,'<script')).Count;bootCandidateScripts=$rows;pluginRoutes=$pluginRoutes;hasPanelText=$html.Contains('DSH 原生侧栏插件探针');host=$base.Authority}|ConvertTo-Json -Depth 6}
finally{if(-not $proc.HasExited){Stop-Process -Id $proc.Id -Force}}
